      "ballot_id": "B001",
      "proposed_laureates": [
        "Frans Pretorius",
        "John G. Baker",
        "Manuela Campanelli"
      ],
      "assessment": {
        "nobel_worthiness": "Stable numerical solutions for binary black-hole mergers made strong-field general relativity calculable and enabled direct comparison with gravitational-wave observations; this is a major achievement in gravitation.",
        "attribution": "Pretorius's breakthrough and the independent breakthroughs by the Baker and Campanelli groups were central to the numerical methods that made long-term merger simulations possible. Shared credit is warranted.",
        "maturity": "The methods have been extensively validated and became essential to interpreting the observed merger signals.",
        "uncertainties": [
          "The precise division of credit among the independently developing groups needs careful historical assessment."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Jean-Loup Puget"
      ],
      "assessment": {
        "nobel_worthiness": "Precision maps of cosmic microwave background anisotropies transformed cosmology into a quantitative field and established the primordial seeds and parameters of the observable universe.",
        "attribution": "Bennett and Puget represent the experimental leadership behind landmark satellite measurements; Spergel's theoretical interpretation helped extract their cosmological significance. The broad collaboration makes individual attribution difficult.",
        "maturity": "Independent observations and decades of analysis have made the results exceptionally robust.",
        "uncertainties": [
          "A prize limited to three people would omit important contributors to the missions and their analysis."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Fabiola Gianotti",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson completed a central prediction of the Standard Model and confirmed the mechanism responsible for electroweak symmetry breaking.",
        "attribution": "This was a vast collaborative achievement. These names represent leadership across ATLAS and CMS, but any small laureate group risks underrepresenting the experiments and the accelerator effort.",
        "maturity": "The discovery has been repeatedly confirmed, and subsequent measurements have established the particle's properties with increasing precision.",
        "uncertainties": [
          "How to recognize a collaboration of this scale within the prize's individual laureate limit."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "Detecting high-energy astrophysical neutrinos opened a new observational window on the universe and established neutrinos as messengers of energetic cosmic processes.",
        "attribution": "Halzen's scientific leadership and the sustained instrumental and organizational contributions of Karle and Spiering merit recognition; the result depended on a large detector collaboration.",
        "maturity": "The astrophysical flux is firmly detected, though identifying its sources and physical origins remains an active area of research.",
        "uncertainties": [
          "The relative credit for the detector, discovery analysis, and broader collaboration requires careful assessment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Michele Parrinello",
        "Roberto Car"
      ],
      "assessment": {
        "nobel_worthiness": "The Car–Parrinello method joined first-principles electronic structure with molecular dynamics, making realistic simulations of materials and chemical systems broadly possible.",
        "attribution": "The central method was a joint achievement of Car and Parrinello, whose names are inseparable from its conception and development.",
        "maturity": "Its influence is long established, with extensive use and many later methodological advances across computational physics and chemistry.",
        "uncertainties": [
          "The boundary between this original contribution and the many subsequent developments in ab initio simulation should be defined."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have pushed precision timekeeping to a new regime and created powerful tools for tests of fundamental physics and applications in metrology.",
        "attribution": "Katori and Ye made leading, complementary contributions to the clock concepts and their experimental realization.",
        "maturity": "The technology is now highly mature, with increasingly precise demonstrations and a clear path to wider use.",
        "uncertainties": [
          "The longer-term reach of clock networks for fundamental discoveries is still developing."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is a remarkable conceptual connection that has reshaped work across quantum field theory, string theory, and black-hole physics.",
        "attribution": "Maldacena's precise conjecture was decisive; Witten and Polyakov made profound contributions to the framework and the wider development of duality.",
        "maturity": "The correspondence has generated a large and technically rich body of work, but its relation to the observed universe remains unestablished.",
        "uncertainties": [
          "The duality has no direct empirical confirmation in the physical setting for which a Nobel prize would be most compelling.",
          "The proposed laureate group spans contributions that are related but historically distinct."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Artur Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution turned quantum principles into a clear communication protocol and helped create the field of quantum information science.",
        "attribution": "Ekert's entanglement-based protocol and the Bennett–Brassard work were foundational, complementary contributions to quantum cryptography.",
        "maturity": "The principles have been experimentally demonstrated and developed into practical systems, although deployment and security assumptions continue to evolve.",
        "uncertainties": [
          "The field's Nobel case may be viewed as less fundamental than its major impact on quantum information and technology.",
          "Credit across the protocols and later experimental developments is broad."
        ]
      }
    }
  ]
